INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 17, 'theory', 'Quiz: structs, enums and match');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 17, 0, 'What does it mean for the enum Shape { Circle(f64), Rect(f64, f64), Point } to be a "sum type"?', '["All variants are stored at the same time", "The variants are added together arithmetically", "At any moment the value is in exactly one variant, with that variant''s own data", "The variants inherit from each other"]', 2, 'A struct is a product (all fields at once), an enum is a sum (one variant out of several). In memory it is a tag plus a shared space for the largest payload.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 17, 1, 'What happens if you forget one of the variants in a match on an enum and do not add _?', '["The compiler refuses to build the program: the patterns do not cover all the variants", "The arm for the forgotten variant runs by default", "The program panics at runtime on that variant", "The forgotten variant is silently skipped"]', 0, 'Exhaustiveness is checked at compile time (error E0004). When you add a new variant to an enum, you get a list of all the places that need updating.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 17, 2, 'Why does Option<Box<i32>> take as much space as Box<i32>?', '["Because Option is just a synonym for Box", "Because the compiler compresses the data", "Because Option stores the value on the heap", "Because None is encoded as a null pointer, and a real Box never has a null address, so no tag is needed"]', 3, 'This is the niche: an unused pointer value is given to None. An Option<u32> has no niche, and its size grows to eight bytes (the tag plus alignment).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 17, 3, 'What does match opt { Some(s) => …, None => … } do by value for opt: Option<String>?', '["Copies the string into s and leaves opt untouched", "Moves the string into s: after the match, the variable opt (as a whole) is unavailable", "Only reads the string without changing the owner", "Panics if opt is Some"]', 1, 'A by-value binding transfers ownership, like an ordinary assignment. If you need to keep opt, match on a reference: match &opt.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 17, 4, 'In what order does derive(PartialOrd, Ord) compare the fields of a struct?', '["Alphabetically by field name", "By field size", "In the order the fields are written in the definition, lexicographically", "Randomly, the order is undefined"]', 2, 'The order of the fields in the definition becomes the comparison order, so swapping lines in a struct can change the sorting.');
